namespace DenTinh.UnityRuntime {
    [Serializable] public class GameSettings {public float master=.8f,music=.55f,sfx=.85f,ui=1;public bool reducedMotion,touch;}
    public sealed class DenTinhGame : MonoBehaviour {
        public Simulation Game;ContentDatabase content;Camera view;Texture2D keyArt;Font font;Material material;AudioSource audioSource,musicSource;AudioClip[] notes;
        readonly Dictionary<string,SpriteRenderer> sprites=new Dictionary<string,SpriteRenderer>();readonly Dictionary<string,LineRenderer> lines=new Dictionary<string,LineRenderer>();readonly HashSet<string> visible=new HashSet<string>();readonly HashSet<Effect> playedFx=new HashSet<Effect>();
        GameSettings settings=new GameSettings();string selected="an",screen="menu",dialogue="",toast="",lastZone="";float toastTime,saveTime,musicTime;int musicNote;Sprite terrain;GUIStyle text,title,small,button,card;bool stylesReady;Vector2 scroll;int moveFinger=-1,aimFinger=-1;Vector2 moveOrigin,aimOrigin,moveTouch,aimTouch;bool touchFire;
        string SaveFolder {get{return Path.Combine(Path.GetDirectoryName(Application.dataPath),"Saves");}}string SavePath {get{return Path.Combine(SaveFolder,"unity-save.json");}}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Boot(){if(FindFirstObjectByType<DenTinhGame>()==null)new GameObject("Đèn Tinh · Game").AddComponent<DenTinhGame>();}
        void Awake(){
            content=CatalogData.Create();Application.targetFrameRate=60;QualitySettings.vSyncCount=1;keyArt=Resources.Load<Texture2D>("Art/KeyArt");font=Font.CreateDynamicFontFromOSFont("Segoe UI",20);Shader shader=Resources.Load<Shader>("PixelSprite");material=new Material(shader!=null?shader:Shader.Find("Sprites/Default"));PixelArt.Material=material;
            GameObject cameraObject=new GameObject("Main Camera");view=cameraObject.AddComponent<Camera>();view.orthographic=true;view.orthographicSize=7.1f;view.backgroundColor=PixelArt.ColorOf("#102936");view.transform.position=new Vector3(11.5f,10,-20);cameraObject.AddComponent<AudioListener>();
            audioSource=gameObject.AddComponent<AudioSource>();musicSource=gameObject.AddComponent<AudioSource>();audioSource.playOnAwake=musicSource.playOnAwake=false;notes=new AudioClip[16];for(int i=0;i<notes.Length;i++)notes[i]=Tone(110*Mathf.Pow(2,i/12f),.9f,.22f,false);
            try{string p=Path.Combine(SaveFolder,"settings.json");if(File.Exists(p))settings=JsonUtility.FromJson<GameSettings>(File.ReadAllText(p))??settings;}catch(Exception e){Debug.LogWarning(e.Message);}
            if(Application.isMobilePlatform)settings.touch=true;NewGame("an",0,false);screen="menu";Game.Paused=true;
        }
        void NewGame(string hero,int cycle,bool play){selected=hero;Game=new Simulation(content,hero,Environment.TickCount&int.MaxValue,cycle);terrain=MakeGround();view.transform.position=new Vector3(Game.Player.position.x,Game.Player.position.y,-20);screen=play?"":"menu";Game.Paused=!play;saveTime=0;playedFx.Clear();if(play){dialogue="Sương nuốt mất tên của Làng Đèn. Bà Năm trao cho con một ngọn đèn còn nhớ đường về.\n\nSăn Trúc Vệ, giữ Đèn Sen và thanh tẩy lò Tro. Đốm và HoaVi sẽ cùng con tìm những ký ức cũ.";screen="dialogue";Game.Paused=true;}}
        void Update(){
            if(Game==null)return;float dt=Mathf.Min(.04f,Time.unscaledDeltaTime);toastTime=Mathf.Max(0,toastTime-dt);
            audioSource.volume=settings.master*settings.sfx;musicSource.volume=settings.master*settings.music*.5f;
            if(Input.GetKeyDown(KeyCode.Escape)){if(screen=="")Open("pause");else if(screen!="menu"&&screen!="death"&&screen!="talent"&&screen!="victory")Resume();}
            if(screen==""){
                Vector2 move=new Vector2((Input.GetKey(KeyCode.D)?1:0)-(Input.GetKey(KeyCode.A)?1:0),(Input.GetKey(KeyCode.W)?1:0)-(Input.GetKey(KeyCode.S)?1:0));move+=new Vector2((Input.GetKey(KeyCode.RightArrow)?1:0)-(Input.GetKey(KeyCode.LeftArrow)?1:0),(Input.GetKey(KeyCode.UpArrow)?1:0)-(Input.GetKey(KeyCode.DownArrow)?1:0));
                Vector3 aim=view.ScreenToWorldPoint(Input.mousePosition);ReadTouch();if(moveTouch.sqrMagnitude>.01f)move=moveTouch;V2 target=touchFire?Game.Player.position+new V2(aimTouch.x,aimTouch.y)*7:new V2(aim.x,aim.y);Game.Input=new GameInput{move=new V2(move.x,move.y),aim=target,attack=Input.GetMouseButton(0)&&Input.mousePosition.y>160||touchFire};
                if(Input.GetKeyDown(KeyCode.Space))Game.Dash();if(Input.GetKeyDown(KeyCode.Q))Game.Skill("q");if(Input.GetKeyDown(KeyCode.E))Game.Skill("e");if(Input.GetKeyDown(KeyCode.R))Game.Skill("r");if(Input.GetKeyDown(KeyCode.H))Game.Heal();if(Input.GetKeyDown(KeyCode.Tab))Game.Swap();if(Input.GetKeyDown(KeyCode.V))Game.Reload();if(Input.GetKeyDown(KeyCode.F))Game.Interact();if(Input.GetKeyDown(KeyCode.I))Open("inventory");if(Input.GetKeyDown(KeyCode.M))Open("map");
            }else{moveTouch=Vector2.zero;touchFire=false;}
            Game.Tick(dt);ProcessEvents();if(Game.PendingLevels>0&&screen=="")Open("talent");
            if(screen!="menu"){saveTime+=dt;if(saveTime>=12){saveTime=0;Save();}}
            Vector3 p=new Vector3(Game.Player.position.x,Game.Player.position.y,-20);float halfW=view.orthographicSize*view.aspect;p.x=Mathf.Clamp(p.x,halfW,Simulation.Width-halfW);p.y=Mathf.Clamp(p.y,view.orthographicSize,Simulation.Height-view.orthographicSize);view.transform.position=Vector3.Lerp(view.transform.position,p,1-Mathf.Exp(-7*dt));if(!settings.reducedMotion&&Game.Shake>0)view.transform.position+=(Vector3)UnityEngine.Random.insideUnitCircle*Game.Shake*.05f;
            Render();Music(dt);
        }
        void ReadTouch(){
            if(!settings.touch)return;foreach(Touch t in Input.touches){
                if(t.phase==TouchPhase.Began&&t.position.y<Screen.height*.55f){if(t.position.x<Screen.width*.35f&&moveFinger<0){moveFinger=t.fingerId;moveOrigin=t.position;}else if(t.position.x>Screen.width*.72f&&aimFinger<0){aimFinger=t.fingerId;aimOrigin=t.position;}}
                if(t.fingerId==moveFinger)moveTouch=Vector2.ClampMagnitude((t.position-moveOrigin)/65,1);if(t.fingerId==aimFinger){aimTouch=Vector2.ClampMagnitude((t.position-aimOrigin)/65,1);touchFire=aimTouch.magnitude>.15f;}
                if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled){if(t.fingerId==moveFinger){moveFinger=-1;moveTouch=Vector2.zero;}if(t.fingerId==aimFinger){aimFinger=-1;touchFire=false;}}
            }
        }
        void ProcessEvents(){while(Game.Events.Count>0){SimEvent e=Game.Events.Dequeue();if(e.kind=="sound"){Sfx(e.text);continue;}if(e.kind=="save"){Save();continue;}if(e.kind=="death"){Open("death");continue;}if(e.kind=="victory"){Save();Open("victory");continue;}if(e.kind=="shop"){Open("shop");continue;}if(e.kind=="dialogue"||e.kind=="memory"){dialogue=e.text;Open("dialogue");continue;}if(e.kind=="level")continue;toast=e.text;toastTime=4.5f;}}
        void Open(string name){screen=name;Game.Paused=true;touchFire=false;moveTouch=Vector2.zero;}
        void Resume(){screen="";Game.Paused=false;if(Game.PendingLevels>0)Open("talent");Save();}
        public void Save(){if(Game==null||Game.Dead||screen=="menu")return;try{Directory.CreateDirectory(SaveFolder);string tmp=SavePath+".tmp";File.WriteAllText(tmp,JsonUtility.ToJson(Game.Capture(),true));if(File.Exists(SavePath))File.Copy(SavePath,SavePath+".bak",true);File.Copy(tmp,SavePath,true);File.Delete(tmp);}catch(Exception e){toast="Chưa lưu được: "+e.Message;toastTime=5;Debug.LogError(e);}}
        void Continue(){try{RunSave data=JsonUtility.FromJson<RunSave>(File.ReadAllText(SavePath));Game=Simulation.Restore(content,data);selected=Game.Hero.id;terrain=MakeGround();screen="";Game.Paused=false;toast="Ngọn đèn vẫn đợi bạn.";toastTime=3;}catch(Exception e){toast="Bản lưu chưa đọc được: "+e.Message;toastTime=6;}}
        void OnApplicationFocus(bool focused){if(!focused&&Game!=null&&screen==""){Open("pause");Save();}}
        void OnApplicationQuit(){Save();}
        void OnApplicationPause(bool paused){if(paused&&Game!=null){if(screen=="")Open("pause");Save();}}
        SpriteRenderer Show(string id,Sprite sprite,V2 at,float scale,Color color,int order){visible.Add(id);SpriteRenderer r;if(!sprites.TryGetValue(id,out r)){GameObject o=new GameObject(id);o.transform.SetParent(transform);r=o.AddComponent<SpriteRenderer>();r.sharedMaterial=material;sprites[id]=r;}r.gameObject.SetActive(true);r.sprite=sprite;r.color=color;r.sortingOrder=order;r.transform.position=new Vector3(at.x,at.y,0);r.transform.localScale=Vector3.one*scale;r.transform.rotation=Quaternion.identity;return r;}
        void Ring(string id,V2 at,float radius,Color color,float progress=1){visible.Add(id);LineRenderer r;if(!lines.TryGetValue(id,out r)){GameObject o=new GameObject(id);o.transform.SetParent(transform);r=o.AddComponent<LineRenderer>();r.sharedMaterial=material;r.useWorldSpace=true;r.loop=false;r.widthMultiplier=.035f;r.sortingOrder=3200;lines[id]=r;}r.gameObject.SetActive(true);r.positionCount=49;r.startColor=r.endColor=color;for(int i=0;i<49;i++){float a=i/48f*Mathf.PI*2*progress;r.SetPosition(i,new Vector3(at.x+Mathf.Cos(a)*radius,at.y+Mathf.Sin(a)*radius,-.1f));}}
        bool InView(V2 p){return Mathf.Abs(p.x-view.transform.position.x)<view.orthographicSize*view.aspect+3&&Mathf.Abs(p.y-view.transform.position.y)<view.orthographicSize+4;}
        int Order(V2 p){return 1500-(int)(p.y*20);}
        void Render(){
            visible.Clear();Show("ground",terrain,new V2(0,0),1,Color.white,-1000);
            for(int i=0;i<Game.Props.Count;i++){Prop o=Game.Props[i];if(!InView(o.position))continue;float scale=o.type=="banyan"?3.1f:o.type=="house"||o.type=="temple"?2.2f:1;Color tint=Color.white;V2 p=Game.Player.position;if(o.type=="tree"&&p.y>o.position.y&&p.y<o.position.y+2&&Mathf.Abs(p.x-o.position.x)<.9f)tint.a=.4f;Show("prop-"+i,PixelArt.Item(o.type,o.variant),o.position,scale,tint,Order(o.position));}
            Show("elder",PixelArt.Item("npc",0),new V2(10.5f,11),1,Color.white,Order(new V2(10.5f,11)));Show("smith",PixelArt.Item("npc",1),new V2(14.5f,8.5f),1,Color.white,Order(new V2(14.5f,8.5f)));Show("well",PixelArt.Item("shrine"),new V2(8.2f,8.6f),.7f,PixelArt.ColorOf("#93d6dc"),1300);
            foreach(Shrine s in Game.Shrines)if(InView(s.position)){Color col=PixelArt.ColorOf(s.active?"#9ef1bd":s.id=="sen"?"#f4b1d7":s.id=="tro"?"#ffd098":"#addfbc");Show("shrine-"+s.id,PixelArt.Item("shrine"),s.position,1.25f,col,Order(s.position));Show("glow-"+s.id,PixelArt.Glow(),s.position+new V2(0,.6f),2,new Color(col.r,col.g,col.b,.25f),1900);if(s.started&&!s.complete)Ring("challenge-"+s.id,s.position,3.6f,new Color(col.r,col.g,col.b,.6f));}
            foreach(Loot l in Game.Drops)if(!l.collected&&InView(l.position)){Sprite item=l.kind=="weapon"?PixelArt.Weapon(content.Weapon(l.weapon)):l.kind=="chest"?PixelArt.Item("chest"):l.kind=="memory"?PixelArt.Item("core"):PixelArt.Dot();Color col=l.kind=="weapon"?PixelArt.ColorOf(content.Weapon(l.weapon).color):l.kind=="gold"?PixelArt.ColorOf("#f3cc7b"):l.kind=="potion"?PixelArt.ColorOf("#efa3be"):Color.white;float scale=l.kind=="gold"||l.kind=="potion"?.7f:l.kind=="memory"?.5f:1;Show(l.id,item,l.position+new V2(0,Mathf.Sin(Game.Time*3+l.position.x)*.04f),scale,col,Order(l.position));}
            foreach(EnemyState e in Game.Enemies)if(e.alive&&InView(e.position)){Color tint=e.hit>0?new Color(1.6f,1.6f,1.6f,1):Color.white;float scale=e.type=="boss"?3:e.miniBoss?1.5f:1;Show(e.id,PixelArt.Item(e.type),e.position,scale,tint,Order(e.position));if(e.burn>0)Show("burn-"+e.id,PixelArt.Glow(),e.position+new V2(0,.5f),.8f,new Color(1,.45f,.1f,.4f),2000);}
            PlayerState player=Game.Player;int frame=player.moving?(int)(Game.Time*10)%4:0;SpriteRenderer hero=Show("hero",PixelArt.Hero(Game.Hero,frame),player.position+new V2(0,player.moving?Mathf.Abs(Mathf.Sin(Game.Time*14))*.03f:0),1,player.invulnerable>0&&Mathf.FloorToInt(Game.Time*12)%2==0?new Color(1,1,1,.6f):Color.white,Order(player.position));hero.flipX=Mathf.Cos(player.facing)<0;
            V2 gunPosition=player.position+V2.Angle(player.facing)*.35f+new V2(0,.45f);SpriteRenderer gun=Show("held-weapon",PixelArt.Weapon(Game.Weapon),gunPosition,.85f,Color.white,Order(player.position)+2);gun.transform.rotation=Quaternion.Euler(0,0,player.facing*Mathf.Rad2Deg);gun.flipY=Mathf.Cos(player.facing)<0;
            V2 pet=player.position+new V2(-.65f,Mathf.Sin(Game.Time*3)*.08f-.35f);Show("Đốm",PixelArt.Item("fox"),pet,.7f,Color.white,Order(pet));Loot secret=Game.Drops.Find(l=>!l.collected&&(l.kind=="chest"||l.kind=="memory")&&V2.Distance(l.position,player.position)<6);if(secret!=null)Ring("dom-guide",secret.position,.5f,new Color(1,.88f,.55f,.55f));
            for(int i=0;i<Game.Bullets.Count;i++){Bullet b=Game.Bullets[i];if(!InView(b.position))continue;SpriteRenderer bulletSprite=Show("bullet-"+i,b.kind=="code"?PixelArt.Weapon(content.Weapon("terminal")):PixelArt.Dot(),b.position,b.kind=="code"?.25f:.7f,PixelArt.ColorOf(b.color),2500);bulletSprite.transform.rotation=Quaternion.Euler(0,0,Mathx.Angle(b.velocity)*Mathf.Rad2Deg);if(b.kind=="arrow")bulletSprite.transform.localScale=new Vector3(1.7f,.35f,1);}
            for(int i=0;i<Game.Dangers.Count;i++){Danger d=Game.Dangers[i];float progress=1-d.time/d.maxTime;Color col=PixelArt.ColorOf(d.color);Ring("danger-"+i,d.position,d.radius,col);Ring("danger-fill-"+i,d.position,d.radius*progress,new Color(col.r,col.g,col.b,.6f));Show("danger-glow-"+i,PixelArt.Glow(),d.position,d.radius*1.7f,new Color(col.r,col.g,col.b,.32f),-50);}
            for(int i=0;i<Game.Effects.Count;i++){Effect e=Game.Effects[i];if(e.kind=="text")continue;Color col=PixelArt.ColorOf(e.color);col.a*=e.time/e.maxTime;if(e.kind=="beam"){Ring("fx-beam-"+i,e.position,.05f,col);LineRenderer beam=lines["fx-beam-"+i];beam.positionCount=5;for(int k=0;k<5;k++){float f=k/4f;V2 pos=e.position+(e.end-e.position)*f;beam.SetPosition(k,new Vector3(pos.x,pos.y+(k%2==1?.12f:0),-.1f));}}
                else{Ring("fx-"+i,e.position,Mathf.Max(.05f,e.radius*(1-e.time/e.maxTime)),col);Show("fx-glow-"+i,PixelArt.Glow(),e.position,e.radius*1.6f,new Color(col.r,col.g,col.b,col.a*.3f),2000);}if(!playedFx.Contains(e)){playedFx.Add(e);if(e.kind=="ultimate"||e.kind=="circuit"||e.kind=="burst")Particles(e.position,e.radius,col);}}
            if(player.shield>0)Ring("shield",player.position+new V2(0,.55f),.75f,PixelArt.ColorOf("#c4b1ff"));if(player.firewall>0)Ring("firewall",player.position,2.4f,PixelArt.ColorOf("#eda9ef"));if(player.overclock>0)for(int i=0;i<2;i++){V2 at=player.position+V2.Angle(Game.Time*3+(i==0?-1:1))*.8f;Show("drone-"+i,PixelArt.Weapon(content.Weapon("compiler")),at,.45f,PixelArt.ColorOf("#7dffe6"),2000);}
            foreach(KeyValuePair<string,SpriteRenderer> pair in sprites)if(!visible.Contains(pair.Key))pair.Value.gameObject.SetActive(false);foreach(KeyValuePair<string,LineRenderer> pair in lines)if(!visible.Contains(pair.Key))pair.Value.gameObject.SetActive(false);if(playedFx.Count>500)playedFx.RemoveWhere(e=>!Game.Effects.Contains(e));
        }
        void Particles(V2 p,float radius,Color col){if(settings.reducedMotion)return;GameObject o=new GameObject("Skill sparks");o.transform.position=new Vector3(p.x,p.y,-.2f);ParticleSystem ps=o.AddComponent<ParticleSystem>();ParticleSystem.MainModule main=ps.main;main.duration=.6f;main.loop=false;main.startLifetime=.5f;main.startSpeed=Mathf.Min(6,radius*2);main.startSize=.07f;main.startColor=col;main.simulationSpace=ParticleSystemSimulationSpace.World;ParticleSystem.EmissionModule emission=ps.emission;emission.rateOverTime=0;ParticleSystem.ShapeModule shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Circle;shape.radius=.1f;ParticleSystemRenderer renderer=o.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=material;renderer.sortingOrder=3500;ps.Emit(26);Destroy(o,1.5f);}
        Sprite MakeGround(){Texture2D t=new Texture2D(480,360,TextureFormat.RGBA32,false);t.filterMode=FilterMode.Point;System.Random rng=new System.Random(Game.Seed+77);Color[] pixels=new Color[480*360];for(int y=0;y<360;y++)for(int x=0;x<480;x++){V2 p=new V2(x/8f,y/8f);string z=Simulation.Zone(p);Color col=PixelArt.ColorOf(Simulation.OnPath(p)?"#8d7858":z=="forest"?"#285a4a":z=="lotus"?"#31565d":z=="ash"?"#665347":z=="ancient"?"#2a4544":"#486c52");float noise=(float)rng.NextDouble()*.06f-.03f;col.r+=noise;col.g+=noise;col.b+=noise;pixels[y*480+x]=col;}t.SetPixels(pixels);t.Apply();return Sprite.Create(t,new Rect(0,0,480,360),Vector2.zero,8);}
        AudioClip Tone(float frequency,float duration,float volume,bool sharp){int rate=22050,n=(int)(rate*duration);float[] data=new float[n];for(int i=0;i<n;i++){float at=i/(float)rate,envelope=Mathf.Min(1,at/.01f)*Mathf.Pow(1-at/duration,2);float wave=Mathf.Sin(at*frequency*Mathf.PI*2);if(sharp)wave+=Mathf.Sin(at*frequency*2*Mathf.PI*2)*.22f;data[i]=wave*envelope*volume;}AudioClip clip=AudioClip.Create("Đèn Tinh tone",n,1,rate,false);clip.SetData(data,0);return clip;}
        void Sfx(string kind){float f=kind=="codeShot"?880:kind=="shoot"?620:kind=="hurt"?130:kind=="dash"?380:kind=="kill"?190:kind=="pickup"?1100:kind=="ultimate"?330:720;AudioClip clip=Tone(f,kind=="ultimate"?.65f:.12f,kind=="shoot"||kind=="codeShot"?.12f:.2f,kind=="codeShot"||kind=="hurt");audioSource.PlayOneShot(clip);Destroy(clip,2);}
        void Music(float dt){if(Game.Paused||screen=="menu")return;string zone=Game.BossStarted&&!Game.Victory?"boss":Simulation.Zone(Game.Player.position);if(lastZone!=zone){lastZone=zone;musicTime=0;musicNote=0;}musicTime-=dt;if(musicTime>0)return;int[] tune=zone=="forest"?new[]{7,9,12,14,12,9,7,4}:zone=="lotus"?new[]{3,7,10,14,10,7,3,0}:zone=="ash"?new[]{0,3,5,7,5,3,0,2}:zone=="boss"?new[]{0,3,5,7,10,7,5,3}:new[]{0,4,7,9,12,9,7,4};musicSource.PlayOneShot(notes[tune[musicNote++%tune.Length]]);musicTime=zone=="boss"?.38f:zone=="forest"?.72f:1.05f;}
        void Styles(){if(stylesReady)return;stylesReady=true;text=new GUIStyle(GUI.skin.label){font=font,fontSize=20,wordWrap=true,richText=true};text.normal.textColor=PixelArt.ColorOf("#e9e4ce");small=new GUIStyle(text){fontSize=15};title=new GUIStyle(text){fontSize=42,fontStyle=FontStyle.Bold};button=new GUIStyle(GUI.skin.button){font=font,fontSize=20,wordWrap=true,padding=new RectOffset(16,16,8,8)};card=new GUIStyle(text){fontSize=18,padding=new RectOffset(18,18,14,14)};}
        void Panel(Rect r,Color? color=null){Color old=GUI.color;GUI.color=color??new Color(.045f,.095f,.14f,.94f);GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=old;}
        bool Button(Rect r,string label){return GUI.Button(r,label,button);}
        void Label(Rect r,string label,bool mini=false){GUI.Label(r,label,mini?small:text);}
        void Bar(Rect r,float value,string label,Color color){Panel(r,new Color(.025f,.05f,.08f,.95f));Panel(new Rect(r.x+2,r.y+2,(r.width-4)*Mathf.Clamp01(value),r.height-4),color);GUIStyle s=new GUIStyle(small){alignment=TextAnchor.MiddleCenter};GUI.Label(r,label,s);}
        void OnGUI(){if(Game==null)return;Styles();float sx=Screen.width/1600f,sy=Screen.height/900f;GUI.matrix=Matrix4x4.TRS(Vector3.zero,Quaternion.identity,new Vector3(sx,sy,1));if(screen=="menu"){Menu();return;}Hud();if(screen!="")Modal();if(toastTime>0){Panel(new Rect(480,125,640,72),new Color(.06f,.14f,.18f,.94f));Label(new Rect(500,137,600,54),toast,true);}if(settings.touch&&screen=="")TouchHud();}
        void Menu(){
            if(keyArt!=null)GUI.DrawTexture(new Rect(0,0,1600,900),keyArt,ScaleMode.ScaleAndCrop);Panel(new Rect(0,0,850,900),new Color(.025f,.07f,.12f,.88f));Label(new Rect(70,75,650,40),"MỘT HÀNH TRÌNH GIỮ LỬA",true);GUI.Label(new Rect(65,120,730,105),"ĐÈN TINH",new GUIStyle(title){fontSize=84});Label(new Rect(72,235,650,40),"MIỀN SƯƠNG LẠC · UNITY 2D");Label(new Rect(72,298,660,80),"Sương nuốt mất tên của một ngôi làng.\nMột ngọn đèn vẫn nhớ đường trở về.");
            for(int i=0;i<content.heroes.Length;i++){HeroDef h=content.heroes[i];Rect r=new Rect(70+i*178,425,165,190);Panel(r,h.id==selected?new Color(.22f,.35f,.34f,.96f):new Color(.07f,.14f,.2f,.96f));if(Button(new Rect(r.x+8,r.y+9,149,47),h.name))selected=h.id;Label(new Rect(r.x+11,r.y+65,145,33),h.role,true);Label(new Rect(r.x+11,r.y+104,145,78),h.desc,true);}
            if(Button(new Rect(70,650,330,66),"Bắt đầu hành trình →"))NewGame(selected,0,true);if(File.Exists(SavePath)&&Button(new Rect(420,650,240,66),"Tiếp tục"))Continue();if(Button(new Rect(70,745,210,47),"Cài đặt"))Open("settings-menu");if(Button(new Rect(295,745,220,47),"Cách chơi")){dialogue="WASD / mũi tên: di chuyển. Chuột: ngắm và giữ trái để bắn.\nSPACE: lướt. Q/E: kỹ năng. R: tuyệt kỹ. H: hồi máu. F: tương tác. TAB: đổi vũ khí. V: nạp băng. M: bản đồ. I: di vật.\n\nBốn nhân vật, 12 vũ khí, 12 di vật, ba thử thách và Hành trình +. Tiến độ Unity lưu riêng trong thư mục Saves cạnh bản chạy.";Open("help-menu");}Label(new Rect(72,835,720,30),"04 NHÂN VẬT / 12 VŨ KHÍ / DI VẬT & KÝ ỨC / 0.2",true);if(screen=="settings-menu"||screen=="help-menu")Modal();
        }
        void Hud(){
            PlayerState p=Game.Player;float fontScale=settings.ui;Panel(new Rect(25,23,350,132));Label(new Rect(43,35,310,30),Game.Hero.name+" · Cấp "+p.level);Bar(new Rect(43,75,310,25),p.hp/p.maxHp,"Máu "+Mathf.CeilToInt(p.hp)+" / "+p.maxHp,PixelArt.ColorOf("#d78677"));Bar(new Rect(43,108,310,16),p.mp/p.maxMp,"Linh lực "+Mathf.FloorToInt(p.mp),PixelArt.ColorOf("#69bdba"));
            Panel(new Rect(25,174,350,104));GUIStyle quest=new GUIStyle(small){fontSize=Mathf.RoundToInt(16*fontScale)};GUI.Label(new Rect(42,189,315,78),Game.Objective(),quest);Label(new Rect(670,30,400,45),ZoneName(Simulation.Zone(p.position)));
            Panel(new Rect(1250,25,325,130));Label(new Rect(1270,40,280,30),"◈ "+p.gold+" xu · Ấn "+Game.Shrines.FindAll(s=>s.active).Count+" / 3");if(Button(new Rect(1270,87,125,46),"Bản đồ M"))Open("map");if(Button(new Rect(1405,87,145,46),"Tạm dừng"))Open("pause");
            Panel(new Rect(25,727,350,145));Label(new Rect(43,740,310,30),Game.Weapon.name+" +"+Game.Active.level);Label(new Rect(43,780,310,30),Game.Active.reload>0?"Đang nạp "+Game.Active.reload.ToString("F1")+"s":Game.Active.ammo+" / "+Game.Weapon.clip+" · V nạp",true);Label(new Rect(43,817,310,40),Game.Hero.id=="hoavi"?"Mã Lệnh "+p.code+" / 8 · Khiên "+p.shield:Passive(Game.Hero.id),true);
            string[] names={"SPACE\nLướt","Q\n"+Game.Hero.q,"E\n"+Game.Hero.e,"R\n"+Game.Hero.r,"H\n"+p.potions+" bình"};float[] cooldown={p.dashTimer,p.qTimer,p.eTimer,100-p.ult,0};for(int i=0;i<5;i++){Rect r=new Rect(460+i*145,763,135,96);if(Button(r,names[i]+(cooldown[i]>0?"\n"+(i==3?(int)p.ult+"%":cooldown[i].ToString("F1")):""))){if(i==0)Game.Dash();if(i==1)Game.Skill("q");if(i==2)Game.Skill("e");if(i==3)Game.Skill("r");if(i==4)Game.Heal();}}
            string near=Game.Nearby();if(near!=""){Panel(new Rect(535,655,530,55));Label(new Rect(555,667,490,40),near);}Label(new Rect(410,870,950,25),"WASD · Chuột bắn · F tương tác · TAB đổi vũ khí · V nạp · I thuộc tính",true);
            EnemyState boss=Game.Enemies.Find(e=>e.alive&&e.type=="boss");if(boss!=null&&V2.Distance(p.position,boss.position)<15)Bar(new Rect(450,95,700,25),boss.hp/boss.maxHp,"Mộc Quỷ · "+(boss.phase==3?"KÝ ỨC VỠ":boss.phase==2?"CUỒNG SƯƠNG":"CỘI ĐA LẠC HỒN"),PixelArt.ColorOf("#c47783"));
            foreach(Effect e in Game.Effects)if(e.kind=="text"){Vector3 point=view.WorldToScreenPoint(new Vector3(e.position.x,e.position.y+(1-e.time/e.maxTime)*.5f,0));Color old=GUI.color;GUI.color=PixelArt.ColorOf(e.color);GUI.Label(new Rect(point.x/Screen.width*1600-30,(1-point.y/Screen.height)*900-20,90,40),e.text,new GUIStyle(text){fontSize=19,fontStyle=FontStyle.Bold});GUI.color=old;}
        }
        static string ZoneName(string zone){return zone=="village"?"Làng Đèn":zone=="forest"?"Rừng Trúc":zone=="lotus"?"Đầm Sen":zone=="ash"?"Đồi Tro":zone=="ancient"?"Cội Đa Lạc Hồn":"Đường Gió";}
        static string Passive(string id){return id=="an"?"Nội tại · Ngọn Lửa Bền Bỉ":id=="linh"?"Nội tại · Nhịp Lá":id=="kiet"?"Nội tại · Lôi Giáp":"Nội tại · Mã Lệnh";}
        void Modal(){
            Panel(new Rect(0,0,1600,900),new Color(.015f,.025f,.055f,.7f));Rect box=new Rect(355,145,890,615);Panel(box,new Color(.06f,.12f,.18f,.98f));float x=390,y=178;GUI.Label(new Rect(x,y,810,65),screen=="talent"?"Chọn cách giữ lửa.":screen=="shop"?"Lò rèn Chú Bảy":screen=="inventory"?Game.Hero.name+" · Thuộc tính":screen=="map"?"Miền Sương Lạc":screen=="death"?"Đèn chưa tắt.":screen=="victory"?"Ngọn đèn tìm được đường về.":screen.Contains("settings")?"Âm thanh & điều khiển":screen=="pause"?"Nghỉ một nhịp.":"Ký ức của ngọn đèn",title);y+=75;
            if(screen=="talent"){RelicDef[] choices=Game.Choices();for(int i=0;i<choices.Length;i++){RelicDef r=choices[i];if(Button(new Rect(x+i*275,y+30,255,280),r.icon+" "+r.name+"\n\n"+r.desc)){Game.ApplyRelic(r.id,true);Resume();}}return;}
            if(screen=="shop"){Label(new Rect(x,y,810,40),"Đang có "+Game.Player.gold+" xu · "+Game.Weapon.name+" +"+Game.Active.level);string[] ids={"weapon","relic","damage","hp","potion"},labels={"Nâng vũ khí · "+(55+Game.Active.level*30)+" xu","Di vật bí ẩn · 105 xu","+5 sát thương · "+(60+Game.Player.level*15)+" xu","+25 máu · "+(60+Game.Player.level*15)+" xu","Bình máu · 20 xu"};for(int i=0;i<ids.Length;i++)if(Button(new Rect(x+(i%2)*410,y+65+(i/2)*82,390,68),labels[i]))Game.Buy(ids[i]);if(Button(new Rect(x,y+340,810,58),"Lên đường"))Resume();return;}
            if(screen=="inventory"){PlayerState p=Game.Player;Label(new Rect(x,y,810,75),"Máu "+Math.Ceiling(p.hp)+"/"+p.maxHp+" · Linh lực "+(int)p.mp+"/"+p.maxMp+" · Giáp "+(int)(p.armor*100)+"%\n"+Passive(Game.Hero.id)+" · Ký ức "+Game.Memories.Count+"/3 · Thành tựu "+Game.Achievements.Count);for(int i=0;i<2;i++){WeaponState w=p.weapons[i];WeaponDef d=content.Weapon(w.id);Label(new Rect(x+i*410,y+85,390,100),"Ô "+(i+1)+" · "+d.name+" +"+w.level+"\n"+d.desc,true);}string list="";foreach(string r in p.relics){RelicDef d=content.Relic(r);if(d!=null)list+=d.name+" · ";}Label(new Rect(x,y+210,810,160),"DI VẬT\n"+(list==""?"Lên cấp, mở rương và đọc ký ức để tìm di vật.":list),true);if(Button(new Rect(x,y+395,810,55),"Tiếp tục"))Resume();return;}
            if(screen.Contains("settings")){Label(new Rect(x,y,400,35),"Âm lượng chung");settings.master=GUI.HorizontalSlider(new Rect(x+420,y+12,350,25),settings.master,0,1);Label(new Rect(x,y+60,400,35),"Nhạc theo vùng");settings.music=GUI.HorizontalSlider(new Rect(x+420,y+72,350,25),settings.music,0,1);Label(new Rect(x,y+120,400,35),"Âm thanh chiến đấu");settings.sfx=GUI.HorizontalSlider(new Rect(x+420,y+132,350,25),settings.sfx,0,1);Label(new Rect(x,y+180,400,35),"Cỡ chữ nhiệm vụ");settings.ui=GUI.HorizontalSlider(new Rect(x+420,y+192,350,25),settings.ui,1,1.4f);settings.reducedMotion=GUI.Toggle(new Rect(x,y+245,810,40),settings.reducedMotion," Giảm rung và hiệu ứng chớp",button);settings.touch=GUI.Toggle(new Rect(x,y+300,810,40),settings.touch," Điều khiển cảm ứng",button);if(Button(new Rect(x,y+380,810,58),"Lưu và đóng")){Directory.CreateDirectory(SaveFolder);File.WriteAllText(Path.Combine(SaveFolder,"settings.json"),JsonUtility.ToJson(settings,true));if(screen=="settings-menu"){screen="menu";Game.Paused=true;}else Resume();}return;}
            if(screen=="map"){Rect map=new Rect(x,y,810,380);Panel(map,new Color(.035f,.09f,.12f,1));foreach(Shrine s in Game.Shrines){Vector2 at=new Vector2(map.x+s.position.x/60*map.width,map.y+(1-s.position.y/45)*map.height);Label(new Rect(at.x-55,at.y-12,140,60),(s.active?"✦ ":"◇ ")+s.name,true);}V2 p=Game.Player.position;Label(new Rect(map.x+p.x/60*map.width-12,map.y+(1-p.y/45)*map.height-12,140,40),"● Bạn",true);Label(new Rect(map.x+310,map.y+35,200,35),"Cội Đa",true);if(Button(new Rect(x,y+400,810,55),"Đóng bản đồ"))Resume();return;}
            if(screen=="pause"){Label(new Rect(x,y,810,90),Game.Hero.name+" · Cấp "+Game.Player.level+" · "+Game.Kills+" quái\nẤn "+Game.Shrines.FindAll(s=>s.active).Count+"/3 · Hành trình +"+Game.Cycle);if(Button(new Rect(x,y+110,395,65),"Tiếp tục"))Resume();if(Button(new Rect(x+415,y+110,395,65),"Cài đặt"))Open("settings");if(Button(new Rect(x,y+195,395,65),"Lưu tiến độ")){Save();toast="Đã lưu hành trình.";toastTime=3;}if(Button(new Rect(x+415,y+195,395,65),"Lưu và về màn đầu")){Save();screen="menu";Game.Paused=true;}if(Button(new Rect(x,y+285,810,60),"Bỏ qua hướng dẫn đầu game")){Game.Tutorial=5;Resume();}return;}
            if(screen=="death"){Label(new Rect(x,y,810,170),"Đốm đưa bạn về Làng Đèn. Giữ vũ khí, di vật và các ấn đã thức tỉnh; mất 10% xu đang mang.");if(Button(new Rect(x,y+300,810,65),"Trở về Làng Đèn →")){Game.Respawn();Resume();}return;}
            if(screen=="victory"){Label(new Rect(x,y,810,220),"Cội đa cúi những cành già. Sương tan khỏi mái đình, khỏi giếng nước, khỏi bàn tay người đang đợi.\n\n"+Game.Hero.name+" · Cấp "+Game.Player.level+" · "+Game.Kills+" quái · "+Game.Deaths+" lần trở về\nHành trình hoàn thành trong "+(int)(Game.Time/60)+" phút.");if(Button(new Rect(x,y+285,810,65),"Tiếp tục khám phá"))Resume();if(Button(new Rect(x,y+365,810,65),"Hành trình + · thế giới mới"))NewGame(Game.Hero.id,Game.Cycle+1,true);return;}
            Label(new Rect(x,y,810,300),dialogue);if(Button(new Rect(x,y+365,810,65),"Mang đèn lên đường →")){if(screen=="help-menu"){screen="menu";Game.Paused=true;}else Resume();}
        }
        void TouchHud(){Panel(new Rect(40,650,160,160),new Color(.12f,.25f,.3f,.4f));Panel(new Rect(1390,650,160,160),new Color(.12f,.25f,.3f,.4f));Label(new Rect(50,815,180,35),"DI CHUYỂN",true);Label(new Rect(1400,815,180,35),"NGẮM / BẮN",true);if(Button(new Rect(1220,700,120,65),"F · Dùng"))Game.Interact();if(Button(new Rect(1220,780,120,65),"⇄ Đổi"))Game.Swap();}
    }
